import java.util.*;
public class BinaryMinHeap { ArrayList<Integer> a=new ArrayList<Integer>(); int p(int i){return(i-1)/2;} int l(int i){return 2*i+1;} void insert(int x){a.add(x);for(int i=a.size()-1;i>0&&a.get(i)<a.get(p(i));i=p(i))swap(i,p(i));} int findMin(){return a.get(0);} int deleteMin(){int m=a.get(0);a.set(0,a.remove(a.size()-1));down(0);return m;} void down(int i){while(l(i)<a.size()){int c=l(i),r=c+1;if(r<a.size()&&a.get(r)<a.get(c))c=r;if(a.get(i)<=a.get(c))break;swap(i,c);i=c;}} void swap(int i,int j){int t=a.get(i);a.set(i,a.get(j));a.set(j,t);} public static void run(){BinaryMinHeap h=new BinaryMinHeap();for(int x:new int[]{9,4,7,1,3})h.insert(x);System.out.println("Heap array="+h.a+", min="+h.findMin()+", deleteMin="+h.deleteMin()+", after="+h.a);System.out.println("Invariant: complete tree shape and parent <= children; operations O(log n).\n");} public static void main(String[] args){run();}}
